import React, { useState } from 'react';
import { DataView } from 'primereact/dataview';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="dataView-accessibility">Accessible DataView</label>
            <DataView 
                id="dataView-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible DataView input"
                placeholder="Enter dataView"
            />
        </div>
    );
}